-- D-98: execute before the new backend, with team invitation writes paused during cutover.
-- The existing unique invite_code index arbitrates every collision. Never extend the original expiry.
SET @exists_col = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'play_team' AND column_name = 'legacy_invite_code');
SET @ddl = IF(@exists_col = 0, 'ALTER TABLE play_team ADD COLUMN legacy_invite_code VARCHAR(32) NULL', 'SELECT 1');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
SET @exists_col = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'play_team' AND column_name = 'legacy_invite_expire_time');
SET @ddl = IF(@exists_col = 0, 'ALTER TABLE play_team ADD COLUMN legacy_invite_expire_time DATETIME NULL', 'SELECT 1');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
SET @exists_idx = (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'play_team' AND index_name = 'uk_play_team_legacy_invite');
SET @ddl = IF(@exists_idx = 0, 'ALTER TABLE play_team ADD UNIQUE KEY uk_play_team_legacy_invite (legacy_invite_code)', 'SELECT 1');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- Collision retry 1/16. IGNORE leaves an old code untouched on duplicate, for the next attempt.
UPDATE IGNORE play_team SET legacy_invite_code = invite_code, legacy_invite_expire_time = expire_time, invite_code = CONCAT(SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + MOD(CONV(HEX(RANDOM_BYTES(1)), 16, 10), 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + MOD(CONV(HEX(RANDOM_BYTES(1)), 16, 10), 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + MOD(CONV(HEX(RANDOM_BYTES(1)), 16, 10), 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + MOD(CONV(HEX(RANDOM_BYTES(1)), 16, 10), 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + MOD(CONV(HEX(RANDOM_BYTES(1)), 16, 10), 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + MOD(CONV(HEX(RANDOM_BYTES(1)), 16, 10), 31), 1))
WHERE CHAR_LENGTH(invite_code) <> 6;

